454				paramIndex++
455				search = search[i:]
456				searchIndex = searchIndex + i
457				continue
458			}
459	
460		Any:
461			// Any node
462			if child := currentNode.anyChild; child != nil {
463				// If any node is found, use remaining path for paramValues
