package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"reflect"
	"strings"
	"testing"
)

// reference matcher: echo semantics (static > param > any), param consumes non-'/' run (>=1 char), any consumes rest
func refMatch(pattern, path string) bool {
	if pattern == "" {
		return path == ""
	}
	switch pattern[0] {
	case '*':
		return true
	case ':':
		if path == "" {
			return false
		}
		i := 0
		for i < len(path) && path[i] != '/' {
			i++
		}
		return refMatch(pattern[1:], path[i:])
	default:
		if path == "" || path[0] != pattern[0] {
			return false
		}
		return refMatch(pattern[1:], path[1:])
	}
}

func TestZZTmpFuzz(t *testing.T) {
	templates := []string{"/", "/a", "/b", "/a/", "/a/b", "/a/:b", "/a/*", "/:id", "/*", "/a/:b/c", "/a/b/c", "/a/b/*", "/:id/:x", "/a/:b/*", "/ab", "/a/bc", "/a/b/:c", "/:id/b"}
	segments := []string{"a", "b", "c", "x", ""}
	rnd := rand.New(rand.NewSource(42))
	bad := 0
	for iter := 0; iter < 4000; iter++ {
		n := 1 + rnd.Intn(4)
		var routes []string
		for i := 0; i < n; i++ {
			routes = append(routes, templates[rnd.Intn(len(templates))])
		}
		// random path
		nseg := rnd.Intn(4)
		parts := make([]string, nseg)
		for i := range parts {
			parts[i] = segments[rnd.Intn(len(segments))]
		}
		path := "/" + strings.Join(parts, "/")

		e := New()
		for _, rt := range routes {
			e.router.Add(http.MethodGet, rt, handlerFunc)
		}
		c := e.NewContext(nil, nil).(*context)
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Errorf("PANIC routes=%v path=%q: %v", routes, path, r)
					bad++
				}
			}()
			e.router.Find(http.MethodGet, path, c)
		}()
		if c.handler == nil {
			t.Errorf("nil handler routes=%v path=%q", routes, path)
			bad++
			continue
		}
		matched := c.handler != NotFoundHandler && c.handler != MethodNotAllowedHandler
		if matched {
			// verify the reported route pattern really matches path
			route := c.Path()
			if route == "" {
				t.Errorf("matched but empty route routes=%v path=%q pnames=%v", routes, path, c.ParamNames())
				bad++
				continue
			}
			if !refMatch(route, path) {
				t.Errorf("MATCHED NON-ROUTABLE routes=%v path=%q -> route=%q pnames=%v pvalues=%v", routes, path, route, c.ParamNames(), c.ParamValues())
				bad++
			}
			// verify params
			for i, name := range c.ParamNames() {
				v := c.ParamValues()[i]
				if name == "*" {
					continue
				}
				if v == "" {
					t.Errorf("empty param routes=%v path=%q route=%q pnames=%v pvalues=%v", routes, path, route, c.ParamNames(), c.ParamValues())
					bad++
				}
			}
		}
		// completeness: if some registered route matches path, handler should not be NotFound
		routable := false
		for _, rt := range routes {
			if refMatch(rt, path) {
				routable = true
				break
			}
		}
		if routable && c.handler == NotFoundHandler {
			t.Errorf("NOT FOUND but routable routes=%v path=%q", routes, path)
			bad++
		}
		if bad > 25 {
			t.Fatalf("too many failures")
		}
	}
	_ = reflect.ValueOf
	_ = fmt.Sprintf
}
EOF
